"use strict";(globalThis.webpackChunkgrc||=[]).push([[63169],{89225(e){e.exports=JSON.parse('{"citeKey":"zou2012sourceaware","slug":"zou-2012-source-aware-3413","title":"A Source-Aware Interrupt Scheduling for Modern Parallel I/O Systems","authors":["H. Zou","X.-H. Sun","S. Ma","X. Duan"],"venue":"IEEE International Parallel and Distributed Processing Symposium (IPDPS\' 12), Shanghai, China","type":"Conference","entryType":"inproceedings","date":"May, 2012","year":2012,"era":"iit","month":5,"doi":"10.1109/ipdps.2012.24","abstract":"Recent technological advances are putting increased pressure on CPU scheduling. On one hand, processors have more cores. On the other hand, I/O systems have become more complex. Intensive research has been conducted on multi/many-core scheduling; however, most of the studies follow the conventional approach and focus on the utilization and load balance of the cores. In this study, we focus on increasing data locality by bringing source information from I/O into the core interrupt scheduling process. The premise is to group interrupts associated for the same I/O request together on the same core, and prove that data locality is more important than core utilization for many applications. Based on this idea, a source-aware affinity interrupt-scheduling scheme is introduced and a prototype system, SAIs, is implemented. Experiment results show that SAIs is feasible and promising; bandwidth shows a 23.57% improvement in a 3-Gigabit NIC environment and in the optimal case without the NIC bottleneck, the bandwidth improvement increases to 53.23%.","hasAbstract":true,"lede":"Recent technological advances are putting increased pressure on CPU scheduling.","links":{"pdf":"https://grc.iit.edu/papers/2012/zou-2012-source-aware-3413.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);